{
  "architecture": {
    "services": [
      {
        "name": "calc",
        "path": "services/calc",
        "language": "go",
        "public_interface": {
          "kind": "ui",
          "elements": [
            {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            },
            {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            },
            {
              "page": "Calc",
              "role": "textbox",
              "name": "Idempotency key"
            }
          ]
        }
      }
    ],
    "concepts": [
      {
        "concept": "number ready",
        "block": "given",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Enter the given number into the Number field."
      },
      {
        "concept": "number result",
        "block": "then",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Compare the displayed Number text with the expected result."
      },
      {
        "concept": "halve",
        "block": "when",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            }
          },
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Idempotency key"
            }
          }
        ],
        "does": "Set Idempotency key to a fresh label for the requested halving and press Halve once. For a repeated request, reuse the label and press Halve again; Number must stay unchanged."
      }
    ],
    "terms": [
      {
        "term": "idempotency key",
        "technical": "The \"Idempotency key\" textbox on the Calc page of the calc service, which carries the request label submitted with a press of the Halve button.",
        "observed_by": "The When step definition for 'halve' types a freshly generated label into the Calc page's Idempotency key textbox before pressing Halve; for a repeated request it types that same label again instead of a fresh one, so the repeat is recognised and the Number field stays unchanged."
      }
    ]
  }
}

{
  "roles": [
    {
      "name": "Product Owner",
      "description": "Owns meanings."
    }
  ],
  "concepts": {
    "given": [
      {
        "concept": "number ready",
        "means": "A number is entered before the action.",
        "terms": []
      }
    ],
    "when": [
      {
        "concept": "halve",
        "means": "Halve the entered number once with the supplied idempotency key.",
        "terms": [
          "idempotency key"
        ]
      }
    ],
    "then": [
      {
        "concept": "number result",
        "means": "Compare the displayed number with an expected value.",
        "terms": []
      },
      {
        "concept": "unused",
        "means": "The settlement ledger has a reconciled nostro balance.",
        "terms": []
      }
    ]
  },
  "glossary": [
    {
      "term": "idempotency key",
      "means": "An idempotency key is the request label a caller supplies with a request. Repeating a request with the same key changes the number only once."
    }
  ],
  "description": "A calculator accepts a number and a request label. Repeating a request with the same label changes the number only once.",
  "language_policy": "The request label is presented to users as an idempotency key. Keep this exact domain name in the product meanings and declare it when needed."
}
